import React, { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';

const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    setIsOpen(false);

    const targetId = href.replace('#', '');
    const element = document.getElementById(targetId);

    if (element) {
        // We calculate the absolute position of the element.
        // We do NOT subtract the navHeight here. 
        // By scrolling to the exact top, the fixed navbar will sit on top of the 
        // target section's top padding (which is large enough: py-24/py-32), 
        // ensuring a clean cut without showing the previous section.
        const elementPosition = element.getBoundingClientRect().top + window.scrollY;
        const offsetPosition = elementPosition;

        window.scrollTo({
            top: offsetPosition,
            behavior: "smooth"
        });
    }
  };

  const navLinks = [
    { name: 'Studio', href: '#studio' },
    { name: 'Portfolio', href: '#work' },
    { name: 'Leistungen', href: '#services' },
    { name: 'Kontakt', href: '#contact' },
  ];

  return (
    <nav
      className={`fixed w-full z-50 transition-all duration-500 ${
        isScrolled ? 'bg-[#F9F9F7]/95 backdrop-blur-md py-4 shadow-sm text-gray-900' : 'bg-transparent py-8 text-gray-800'
      }`}
    >
      <div className="container mx-auto px-6 md:px-12 flex justify-between items-center">
        {/* Logo */}
        <a href="#" onClick={(e) => { e.preventDefault(); window.scrollTo({ top: 0, behavior: 'smooth' }); }} className="flex items-center gap-3 group z-50 hover-trigger">
            {/* 
                PLEASE NOTE: 
                I have set the src to "/logo.png". 
                You need to add your logo image file to your public folder and name it "logo.png".
            */}
            <img 
                src="/logo.png" 
                alt="AK Film Studio" 
                className="h-12 w-auto object-contain mix-blend-multiply"
                onError={(e) => {
                    // Fallback to text if image is not found
                    e.currentTarget.style.display = 'none';
                    e.currentTarget.nextElementSibling?.classList.remove('hidden');
                }}
            />
            {/* Fallback Text Logo in case image is missing */}
            <div className="hidden flex flex-col items-center">
                <span className={`text-2xl font-serif tracking-widest transition-colors ${isScrolled ? 'text-gray-900' : 'text-gray-900'}`}>
                    AK
                </span>
            </div>

            <div className="h-8 w-[1px] bg-brand/50 mx-2"></div>
            <div className="flex flex-col">
                <span className={`text-xs uppercase tracking-[0.2em] font-medium ${isScrolled ? 'text-gray-600' : 'text-gray-600'}`}>
                    Film Studio
                </span>
                <span className="text-[9px] text-brand tracking-widest uppercase">
                    Vorarlberg
                </span>
            </div>
        </a>

        {/* Desktop Menu */}
        <div className="hidden md:flex space-x-12">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              onClick={(e) => scrollToSection(e, link.href)}
              className={`text-xs uppercase tracking-[0.2em] font-medium relative group/link hover-trigger transition-colors ${isScrolled ? 'text-gray-600 hover:text-black' : 'text-gray-700 hover:text-black'}`}
            >
              {link.name}
              <span className="absolute -bottom-2 left-0 w-0 h-[1px] bg-brand transition-all duration-300 group-hover/link:w-full"></span>
            </a>
          ))}
        </div>

        {/* Mobile Menu Button */}
        <button
          onClick={() => setIsOpen(!isOpen)}
          className={`md:hidden z-50 hover-trigger focus:outline-none ${isOpen ? 'text-gray-900' : 'text-gray-900'}`}
        >
          {isOpen ? <X size={28} /> : <Menu size={28} />}
        </button>

        {/* Mobile Overlay */}
        <div
          className={`fixed inset-0 bg-[#F9F9F7] flex flex-col items-center justify-center space-y-8 transition-all duration-500 md:hidden ${
            isOpen ? 'opacity-100 translate-y-0 pointer-events-auto' : 'opacity-0 -translate-y-10 pointer-events-none'
          }`}
        >
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              onClick={(e) => scrollToSection(e, link.href)}
              className="text-3xl uppercase font-serif tracking-widest text-gray-800 hover:text-brand transition-colors"
            >
              {link.name}
            </a>
          ))}
        </div>
      </div>
    </nav>
  );
};

