import React, { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';

const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    setIsOpen(false);

    const targetId = href.replace('#', '');
    const element = document.getElementById(targetId);

    if (element) {
        // Element exists on current page (Home) -> Smooth Scroll
        const elementPosition = element.getBoundingClientRect().top + window.scrollY;
        // Scroll to exact top 
        const offsetPosition = elementPosition;

        window.scrollTo({
            top: offsetPosition,
            behavior: "smooth"
        });

        // Update URL hash without jumping
        window.history.pushState(null, '', href);
    } else {
        // Element does not exist (we are on Impressum/Datenschutz) -> Navigate to Home
        window.location.hash = targetId;
    }
  };

  const navigateHome = (e: React.MouseEvent<HTMLAnchorElement>) => {
      e.preventDefault();
      // If we are not on home (hash is present and not empty), go to home
      if (window.location.hash && window.location.hash !== '#') {
          window.location.hash = '';
          window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
          // Already on home, just scroll top
          window.scrollTo({ top: 0, behavior: 'smooth' });
      }
  };

  const navLinks = [
    { name: 'Studio', href: '#studio' },
