const FloatingCamera: React.FC = () => {
  const [scrollY, setScrollY] = useState(0);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  // Update scroll position for rotation
  useEffect(() => {
    const handleScroll = () => setScrollY(window.scrollY);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Track mouse for 3D tilt
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      const { innerWidth, innerHeight } = window;
      const x = (e.clientX - innerWidth / 2) / 20; // Sensitivity
      const y = (e.clientY - innerHeight / 2) / 20;
      setMousePos({ x, y });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  // Calculate rotation based on scroll
  const rotation = scrollY * 0.15;

  return (
    <div className="fixed bottom-8 right-8 z-40 hidden md:block perspective-[1000px]">
      <div 
        className="relative w-32 h-32 md:w-40 md:h-40 transition-transform duration-100 ease-out"
        style={{
          transform: `rotateX(${mousePos.y * -1}deg) rotateY(${mousePos.x}deg)`
        }}
      >
        {/* The Rolling Ring (Outer) */}
        <div 
           className="absolute inset-0 rounded-full border border-gray-300/30 border-dashed shadow-2xl"
