                                <span className="text-sm">Portrait (9:16)</span>
                            </button>
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs uppercase tracking-widest text-gray-400 mb-3">Kreative Vision (Optional)</label>
                        <textarea 
                            value={prompt}
                            onChange={(e) => setPrompt(e.target.value)}
                            placeholder="Z.B. Langsame Kamerafahrt, Blätter im Wind, weiches Licht..."
                            className="w-full bg-black/20 border border-gray-700 rounded-sm p-3 text-sm text-white placeholder-gray-600 focus:outline-none focus:border-brand transition-colors resize-none h-24"
                        />
                    </div>
                </div>

                {/* Error Message */}
                {error && (
                    <div className="p-4 bg-red-900/20 border border-red-900/50 rounded flex items-start gap-3 text-red-200 text-sm">
                        <AlertCircle size={18} className="mt-0.5 shrink-0" />
                        <p>{error}</p>
                    </div>
                )}

                {/* Action Button */}
                <button 
                    onClick={handleGenerate}
                    disabled={!imageFile || isGenerating}
                    className={`w-full py-4 text-xs uppercase tracking-[0.2em] font-medium transition-all duration-300 flex items-center justify-center gap-3
                        ${!imageFile || isGenerating 
                            ? 'bg-gray-800 text-gray-500 cursor-not-allowed border border-transparent' 
                            : 'bg-white text-black hover:bg-brand hover:text-white border border-transparent'
                        }`}
                >
                    {isGenerating ? (
                        <>
                            <Loader2 className="animate-spin" size={16} />
                            <span>Generiere...</span>
                        </>
                    ) : (
                        <>
                            <Film size={16} />
