            {/* Right: Preview / Result */}
            <div className="flex flex-col items-center justify-center h-full min-h-[400px]">
                <TiltWrapper className="w-full relative group" maxTilt={5}>
                    <div className={`relative w-full rounded-sm overflow-hidden shadow-2xl bg-black border border-white/10 flex items-center justify-center
