                                <h4 className="text-xl font-serif text-gray-500 mb-2">Warte auf Regie</h4>
                                <p className="text-xs text-gray-600 uppercase tracking-widest">Dein Meisterwerk erscheint hier</p>
                            </div>
                        )}

                        {/* Loading Overlay */}
                        {isGenerating && (
                            <div className="absolute inset-0 bg-black/80 backdrop-blur-sm z-20 flex flex-col items-center justify-center">
                                <div className="relative">
                                    <div className="w-16 h-16 border-t-2 border-b-2 border-brand rounded-full animate-spin"></div>
                                    <div className="w-16 h-16 border-r-2 border-l-2 border-white/20 rounded-full animate-spin absolute inset-0 reverse-spin"></div>
                                </div>
                                <div className="mt-8 text-center space-y-1">
                                    <p className="text-brand text-xs uppercase tracking-widest font-medium">Rendering</p>
                                    <p className="text-white font-serif text-lg">AI Processing</p>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Decorative Elements */}
                    <div className="absolute -z-10 -top-4 -right-4 w-full h-full border border-gray-700/50 rounded-sm"></div>
                    <div className="absolute -z-10 -bottom-4 -left-4 w-full h-full bg-gray-800/20 rounded-sm"></div>
                </TiltWrapper>
            </div>
        </div>
      </div>
    </section>
  );
};

