import React, { useState, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Upload, Film, Loader2, Play, Monitor, Smartphone, AlertCircle } from 'lucide-react';
import TiltWrapper from './TiltWrapper';

const AiStudio: React.FC = () => {
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [prompt, setPrompt] = useState('');
  const [aspectRatio, setAspectRatio] = useState<'16:9' | '9:16'>('16:9');
  const [isGenerating, setIsGenerating] = useState(false);
  const [loadingStep, setLoadingStep] = useState('');
  const [generatedVideoUrl, setGeneratedVideoUrl] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setImageFile(file);
      setPreviewUrl(URL.createObjectURL(file));
      setGeneratedVideoUrl(null);
      setError(null);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = error => reject(error);
    });
  };

  const handleGenerate = async () => {
    if (!imageFile) return;

    setError(null);
    setIsGenerating(true);
    setLoadingStep('Prüfe Zugang...');

    try {
      // 1. Check/Request API Key
      // Cast window to any to avoid type conflicts with global AIStudio type
      const aistudio = (window as any).aistudio;
      if (aistudio && typeof aistudio.hasSelectedApiKey === 'function') {
        const hasKey = await aistudio.hasSelectedApiKey();
        if (!hasKey) {
            await aistudio.openSelectKey();
            // Re-check after dialog
            const hasKeyNow = await aistudio.hasSelectedApiKey();
            if (!hasKeyNow) {
                throw new Error("API Key Auswahl erforderlich für die Generierung.");
            }
        }
      }

      // 2. Initialize Client
      setLoadingStep('Initialisiere AI Studio...');
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const base64Image = await fileToBase64(imageFile);

      // 3. Start Generation
      setLoadingStep('Analysiere Bild & Starte Veo...');

      // Default cinematic prompt if empty
      const finalPrompt = prompt.trim() || "Cinematic slow motion movement, high quality, photorealistic, 4k detail, ambient lighting";

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: finalPrompt,
        image: {
          imageBytes: base64Image,
          mimeType: imageFile.type,
        },
        config: {
          numberOfVideos: 1,
          aspectRatio: aspectRatio,
          resolution: '720p' // 'fast' model works best with 720p or 1080p
        }
      });

      // 4. Poll for Completion
      setLoadingStep('Generiere Video (dies kann einen Moment dauern)...');

      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 5000)); // Poll every 5s
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      if (operation.error) {
          throw new Error(operation.error.message || "Generierung fehlgeschlagen.");
      }

      // 5. Fetch and Display
      setLoadingStep('Lade Ergebnis...');
      const videoUri = operation.response?.generatedVideos?.[0]?.video?.uri;

      if (!videoUri) throw new Error("Keine Video-URI erhalten.");

      // Fetch with key appended
      const response = await fetch(`${videoUri}&key=${process.env.API_KEY}`);
      if (!response.ok) throw new Error("Fehler beim Laden des Videos.");

      const blob = await response.blob();
      const localUrl = URL.createObjectURL(blob);
      setGeneratedVideoUrl(localUrl);

    } catch (err: any) {
      console.error(err);
      setError(err.message || "Ein unbekannter Fehler ist aufgetreten.");
    } finally {
      setIsGenerating(false);
      setLoadingStep('');
    }
  };

  return (
    <section id="ai-lab" className="py-32 bg-[#1a1a1a] text-white relative overflow-hidden">
        {/* Background Texture */}
        <div className="absolute inset-0 opacity-10 pointer-events-none" style={{
            backgroundImage: `url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='1'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")`
        }}></div>

      <div className="container mx-auto px-6 md:px-12 relative z-10">

        {/* Header */}
        <div className="text-center mb-16">
            <span className="text-brand text-xs tracking-[0.3em] uppercase block mb-4">Beta Feature</span>
            <h2 className="text-4xl md:text-6xl font-serif text-white mb-6">AI Cinema <span className="text-brand italic font-serif-alt">Lab</span></h2>
            <p className="text-gray-400 max-w-xl mx-auto font-light">
                Erwecke deine Fotos zum Leben. Nutze unsere experimentelle Google Veo Technologie, um statische Momente in bewegende Erinnerungen zu verwandeln.
            </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 lg:gap-24 items-start max-w-6xl mx-auto">

            {/* Left: Controls */}
            <div className="space-y-8 bg-white/5 p-8 rounded-sm border border-white/10 backdrop-blur-sm">

                {/* Upload Area */}
                <div 
                    className={`border-2 border-dashed rounded-sm p-8 text-center transition-all cursor-pointer group ${imageFile ? 'border-brand bg-brand/5' : 'border-gray-600 hover:border-gray-400 hover:bg-white/5'}`}
                    onClick={() => fileInputRef.current?.click()}
                >
                    <input 
                        type="file" 
                        ref={fileInputRef} 
                        onChange={handleFileChange} 
                        accept="image/png, image/jpeg, image/webp"
                        className="hidden" 
                    />

                    {imageFile ? (
                        <div className="relative">
                            <img src={previewUrl!} alt="Preview" className="h-48 mx-auto object-contain rounded shadow-lg mb-4" />
                            <p className="text-sm text-brand font-medium truncate max-w-xs mx-auto">{imageFile.name}</p>
                            <p className="text-xs text-gray-400 mt-1">Klicken zum Ändern</p>
                        </div>
                    ) : (
                        <div className="py-8">
                            <Upload className="w-12 h-12 text-gray-500 mx-auto mb-4 group-hover:text-brand transition-colors" />
                            <h3 className="text-lg font-serif mb-2">Foto hochladen</h3>
                            <p className="text-xs text-gray-500 uppercase tracking-widest">JPG, PNG bis 10MB</p>
                        </div>
                    )}
                </div>

                {/* Settings */}
                <div className="space-y-6">
                    <div>
                        <label className="block text-xs uppercase tracking-widest text-gray-400 mb-3">Format wählen</label>
                        <div className="grid grid-cols-2 gap-4">
                            <button 
                                onClick={() => setAspectRatio('16:9')}
                                className={`flex items-center justify-center gap-2 py-3 px-4 rounded-sm border transition-all ${aspectRatio === '16:9' ? 'border-brand bg-brand text-white' : 'border-gray-700 hover:border-gray-500 text-gray-400'}`}
                            >
                                <Monitor size={16} />
                                <span className="text-sm">Landscape (16:9)</span>
                            </button>
                            <button 
                                onClick={() => setAspectRatio('9:16')}
                                className={`flex items-center justify-center gap-2 py-3 px-4 rounded-sm border transition-all ${aspectRatio === '9:16' ? 'border-brand bg-brand text-white' : 'border-gray-700 hover:border-gray-500 text-gray-400'}`}
                            >
                                <Smartphone size={16} />
                                <span className="text-sm">Portrait (9:16)</span>
                            </button>
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs uppercase tracking-widest text-gray-400 mb-3">Kreative Vision (Optional)</label>
                        <textarea 
                            value={prompt}
                            onChange={(e) => setPrompt(e.target.value)}
                            placeholder="Z.B. Langsame Kamerafahrt, Blätter im Wind, weiches Licht..."
                            className="w-full bg-black/20 border border-gray-700 rounded-sm p-3 text-sm text-white placeholder-gray-600 focus:outline-none focus:border-brand transition-colors resize-none h-24"
                        />
                    </div>
