import React, { useState } from 'react';
import { X, Sparkles, Loader2, Film } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface AiModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const AiModal: React.FC<AiModalProps> = ({ isOpen, onClose }) => {
  const [names, setNames] = useState('');
  const [location, setLocation] = useState('');
  const [vibe, setVibe] = useState('');
  const [result, setResult] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  if (!isOpen) return null;

  const generateStory = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setResult('');

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) {
        setResult("Fehler: API Key fehlt. Bitte konfigurieren Sie VITE_API_KEY in der .env Datei.");
        setIsLoading(false);
        return;
      }

      const ai = new GoogleGenAI({ apiKey });

      const prompt = `Du bist ein weltklasse Regisseur für cinematische Hochzeitsfilme.
      Erstelle ein kurzes, poetisches und visuelles Film-Treatment (Storyboard-Beschreibung) für folgendes Paar:

      Namen: ${names}
      Ort: ${location}
      Stil/Vibe: ${vibe}

      Beschreibe 3 Schlüsselszenen. Fokussiere dich auf Lichtstimmung, Kameraführung (Drohne, Close-up) und Emotionen.
      Schreibe elegant, emotional und professionell auf Deutsch. Halte es unter 200 Wörtern.`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
      });

      setResult(response.text || "Keine Antwort generiert.");
    } catch (error) {
      console.error(error);
      setResult("Ein Fehler ist aufgetreten. Bitte versuchen Sie es später erneut.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center px-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity"
        onClick={onClose}
      ></div>

      {/* Modal Content */}
      <div className="relative bg-[#F9F9F7] w-full max-w-xl shadow-2xl overflow-hidden animate-[fadeIn_0.3s_ease-out]">

        {/* Header */}
        <div className="bg-gray-900 text-white p-6 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <Sparkles className="text-brand w-5 h-5" />
            <h2 className="font-serif text-xl tracking-wide">Cinematic Vision AI</h2>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">
            <X size={24} />
          </button>
        </div>

        <div className="p-8">
          {!result ? (
            <form onSubmit={generateStory} className="space-y-6">
              <p className="text-gray-500 font-light text-sm">
                Lass unsere KI eine erste Vision für euren Hochzeitsfilm entwerfen. Erzähl uns kurz von euch.
              </p>

              <div className="space-y-4">
                <div>
                  <label className="block text-xs uppercase tracking-widest text-gray-500 mb-2">Eure Namen</label>
                  <input 
                    type="text" 
                    required
                    value={names}
                    onChange={(e) => setNames(e.target.value)}
                    placeholder="z.B. Anna & Lukas"
                    className="w-full bg-white border border-gray-200 p-3 focus:outline-none focus:border-brand transition-colors font-serif"
                  />
                </div>

                <div>
                  <label className="block text-xs uppercase tracking-widest text-gray-500 mb-2">Location / Ort</label>
                  <input 
                    type="text" 
                    required
                    value={location}
                    onChange={(e) => setLocation(e.target.value)}
                    placeholder="z.B. Villa Raczynski, Bregenz"
                    className="w-full bg-white border border-gray-200 p-3 focus:outline-none focus:border-brand transition-colors font-serif"
                  />
                </div>

                <div>
                  <label className="block text-xs uppercase tracking-widest text-gray-500 mb-2">Vibe / Stil</label>
                  <select 
                    value={vibe}
                    onChange={(e) => setVibe(e.target.value)}
                    className="w-full bg-white border border-gray-200 p-3 focus:outline-none focus:border-brand transition-colors font-serif text-gray-700"
                  >
                    <option value="" disabled selected>Wähle einen Stil</option>
                    <option value="Romantisch & Golden Hour">Romantisch & Golden Hour</option>
                    <option value="Moody & Cineastisch">Moody & Cineastisch</option>
                    <option value="Modern & Editorial">Modern & Editorial</option>
                    <option value="Vintage & Super8">Vintage & Super 8 Look</option>
                  </select>
                </div>
              </div>

              <button 
                type="submit" 
                disabled={isLoading || !vibe}
                className="w-full bg-gray-900 text-white py-4 mt-4 uppercase tracking-[0.2em] text-xs hover:bg-brand transition-colors duration-500 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isLoading ? (
                  <>
                    <Loader2 className="animate-spin w-4 h-4" />
                    Entwickle Vision...
                  </>
                ) : (
                  <>
                    Vision Generieren
                  </>
                )}
              </button>
            </form>
          ) : (
            <div className="animate-[fadeIn_0.5s_ease-out]">
               <div className="mb-6 border-l-2 border-brand pl-6">
                  <h3 className="font-serif text-2xl text-gray-900 mb-2">Das Konzept</h3>
                  <div className="text-gray-600 font-light leading-relaxed whitespace-pre-line font-serif-alt text-lg">
                    {result}
                  </div>
               </div>

               <button 
                onClick={() => setResult('')}
                className="text-xs uppercase tracking-widest text-gray-400 hover:text-gray-900 border-b border-transparent hover:border-gray-900 pb-1 transition-all"
               >
                 Neue Vision erstellen
               </button>
            </div>
          )}
        </div>

        {/* Footer Accent */}
        <div className="h-1 w-full bg-gradient-to-r from-gray-900 via-brand to-gray-900"></div>
      </div>
    </div>
  );
};

