import React, { useState } from 'react';
import { X, Sparkles, Loader2 } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface AiModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const AiModal: React.FC<AiModalProps> = ({ isOpen, onClose }) => {
  const [names, setNames] = useState('');
  const [location, setLocation] = useState('');
  const [vibe, setVibe] = useState('');
  const [result, setResult] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  if (!isOpen) return null;

  const generateStory = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setResult('');

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) {
        setResult("Fehler: API Key fehlt. Bitte prüfen Sie Ihre Vercel Environment Variables.");
        setIsLoading(false);
        return;
      }

      const ai = new GoogleGenAI({ apiKey });

      const prompt = `Du bist ein weltklasse Regisseur für cinematische Hochzeitsfilme.
      Erstelle ein kurzes, poetisches und visuelles Film-Treatment (Storyboard-Beschreibung) für folgendes Paar:

      Namen: ${names}
      Ort: ${location}
      Stil/Vibe: ${vibe}

      Beschreibe 3 Schlüsselszenen. Fokussiere dich auf Lichtstimmung, Kameraführung (Drohne, Close-up) und Emotionen.
      Schreibe elegant, emotional und professionell auf Deutsch. Halte es unter 200 Wörtern.`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
      });

      setResult(response.text || "Keine Antwort generiert.");
    } catch (error) {
      console.error(error);
      setResult("Ein Fehler ist aufgetreten. Bitte versuchen Sie es später erneut.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center px-4">
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity"
        onClick={onClose}
      ></div>

      <div className="relative bg-[#F9F9F7] w-full max-w-xl shadow-2xl overflow-hidden animate-[fadeIn_0.3s_ease-out]">
        <div className="bg-gray-900 text-white p-6 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <Sparkles className="text-brand w-5 h-5" />
            <h2 className="font-serif text-xl tracking-wide">Cinematic Vision AI</h2>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">
            <X size={24} />
          </button>
        </div>

        <div className="p-8">
          {!result ? (
            <form onSubmit={generateStory} className="space-y-6">
              <p className="text-gray-500 font-light text-sm">
                Lass unsere KI eine erste Vision für euren Hochzeitsfilm entwerfen.
              </p>

              <div className="space-y-4">
                <div>
                  <label className="block text-xs uppercase tracking-widest text-gray-500 mb-2">Eure Namen</label>
                  <input 
                    type="text" 
                    required
                    value={names}
                    onChange={(e) => setNames(e.target.value)}
                    placeholder="z.B. Anna & Lukas"
                    className="w-full bg-white border border-gray-200 p-3 focus:outline-none focus:border-brand transition-colors font-serif"
                  />
                </div>

                <div>
                  <label className="block text-xs uppercase tracking-widest text-gray-500 mb-2">Location</label>
                  <input 
                    type="text" 
                    required
                    value={location}
                    onChange={(e) => setLocation(e.target.value)}
                    placeholder="z.B. Villa Raczynski"
                    className="w-full bg-white border border-gray-200 p-3 focus:outline-none focus:border-brand transition-colors font-serif"
                  />
                </div>

                <div>
                  <label className="block text-xs uppercase tracking-widest text-gray-500 mb-2">Vibe</label>
                  <select 
                    value={vibe}
                    onChange={(e) => setVibe(e.target.value)}
                    className="w-full bg-white border border-gray-200 p-3 focus:outline-none focus:border-brand transition-colors font-serif text-gray-700"
                  >
                    <option value="" disabled selected>Wähle einen Stil</option>
                    <option value="Romantisch & Golden Hour">Romantisch & Golden Hour</option>
                    <option value="Moody & Cineastisch">Moody & Cineastisch</option>
                    <option value="Modern & Editorial">Modern & Editorial</option>
                    <option value="Vintage & Super8">Vintage & Super 8 Look</option>
                  </select>
                </div>
              </div>

              <button 
                type="submit" 
                disabled={isLoading || !vibe}
                className="w-full bg-gray-900 text-white py-4 mt-4 uppercase tracking-[0.2em] text-xs hover:bg-brand transition-colors duration-500 flex items-center justify-center gap-2 disabled:opacity-50"
              >
                {isLoading ? <Loader2 className="animate-spin w-4 h-4" /> : "Vision Generieren"}
              </button>
            </form>
          ) : (
            <div className="animate-[fadeIn_0.5s_ease-out]">
               <div className="mb-6 border-l-2 border-brand pl-6">
                  <h3 className="font-serif text-2xl text-gray-900 mb-2">Das Konzept</h3>
                  <div className="text-gray-600 font-light leading-relaxed whitespace-pre-line font-serif-alt text-lg">
                    {result}
                  </div>
               </div>
               <button 
                onClick={() => setResult('')}
                className="text-xs uppercase tracking-widest text-gray-400 hover:text-gray-900 border-b border-transparent hover:border-gray-900 pb-1 transition-all"
               >
                 Neue Vision erstellen
               </button>
            </div>
          )}
        </div>
        <div className="h-1 w-full bg-gradient-to-r from-gray-900 via-brand to-gray-900"></div>
      </div>
    </div>
  );
};

export default AiModal;

import React, { useState, useEffect } from 'react';
import { Menu, X, Sparkles } from 'lucide-react';

interface NavbarProps {
  onOpenAi?: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ onOpenAi }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    setIsOpen(false);

    const targetId = href.replace('#', '');
    const element = document.getElementById(targetId);

    if (element) {
        const elementPosition = element.getBoundingClientRect().top + window.scrollY;
        const offsetPosition = elementPosition;

        window.scrollTo({
            top: offsetPosition,
            behavior: "smooth"
        });

        try {
            window.history.pushState(null, '', href);
        } catch (e) {
            window.location.hash = targetId;
        }
    } else {
        window.location.hash = targetId;
    }
  };

  const navigateHome = (e: React.MouseEvent<HTMLAnchorElement>) => {
      e.preventDefault();
      if (window.location.hash) {
          try {
             window.history.pushState("", document.title, window.location.pathname + window.location.search);
             window.location.hash = ''; 
          } catch (e) {
             window.location.hash = ''; 
          }
      } 
      window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const navLinks = [
    { name: 'Studio', href: '#studio' },
    { name: 'Portfolio', href: '#work' },
    { name: 'Leistungen', href: '#services' },
    { name: 'Kontakt', href: '#contact' },
  ];

  return (
    <nav
      className={`fixed w-full z-50 transition-all duration-500 ${
        isScrolled 
            ? 'bg-[#E6E5E3]/90 backdrop-blur-md py-4 border-b border-gray-200 text-gray-900 shadow-sm' 
            : 'bg-transparent py-8 text-white'
      }`}
    >
      <div className="container mx-auto px-6 md:px-12 flex justify-between items-center">
        {/* Logo */}
        <a href="#" onClick={navigateHome} className="flex items-center gap-3 group z-50 hover-trigger">
            <img 
                src="/logo.png" 
                alt="AK Film Studio" 
                className={`h-12 w-auto object-contain transition-all duration-300 ${isScrolled ? '' : 'filter brightness-0 invert'}`}
                onError={(e) => {
                    e.currentTarget.style.display = 'none';
                    e.currentTarget.nextElementSibling?.classList.remove('hidden');
                }}
            />
            <div className="hidden flex flex-col items-center">
                <span className={`text-2xl font-serif tracking-widest transition-colors ${isScrolled ? 'text-gray-900' : 'text-white'}`}>
                    AK
                </span>
            </div>
            <div className="h-8 w-[1px] bg-brand/50 mx-2"></div>
            <div className="flex flex-col justify-center h-full">
                <span className={`text-xs uppercase tracking-[0.2em] font-medium ${isScrolled ? 'text-gray-600' : 'text-gray-300'}`}>
                    Film Studio
                </span>
            </div>
        </a>

        {/* Desktop Menu */}
        <div className="hidden md:flex items-center space-x-12">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              onClick={(e) => scrollToSection(e, link.href)}
              className={`text-xs uppercase tracking-[0.2em] font-medium relative group/link hover-trigger transition-colors ${
                  isScrolled 
                    ? 'text-gray-600 hover:text-black' 
                    : 'text-gray-200 hover:text-white'
                }`}
            >
              {link.name}
              <span className="absolute -bottom-2 left-0 w-0 h-[1px] bg-brand transition-all duration-300 group-hover/link:w-full"></span>
            </a>
          ))}

           {onOpenAi && (
            <button
                onClick={onOpenAi}
                className={`flex items-center gap-2 px-4 py-2 border rounded-sm transition-all duration-300 hover-trigger ${
                    isScrolled
                    ? 'border-gray-300 text-gray-900 hover:bg-gray-900 hover:text-white'
                    : 'border-white/30 text-white hover:bg-white hover:text-gray-900'
                }`}
            >
                <Sparkles size={14} />
                <span className="text-[10px] uppercase tracking-[0.2em] font-bold">Vision AI</span>
            </button>
           )}
        </div>

        {/* Mobile Menu Button */}
        <button
          onClick={() => setIsOpen(!isOpen)}
          className={`md:hidden z-50 hover-trigger focus:outline-none ${isOpen ? 'text-gray-900' : (isScrolled ? 'text-gray-900' : 'text-white')}`}
        >
          {isOpen ? <X size={28} /> : <Menu size={28} />}
        </button>

        {/* Mobile Overlay */}
        <div
          className={`fixed inset-0 bg-[#E6E5E3] flex flex-col items-center justify-center space-y-8 transition-all duration-500 md:hidden ${
            isOpen ? 'opacity-100 translate-y-0 pointer-events-auto' : 'opacity-0 -translate-y-10 pointer-events-none'
          }`}
        >
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              onClick={(e) => scrollToSection(e, link.href)}
              className="text-3xl uppercase font-serif tracking-widest text-gray-800 hover:text-brand transition-colors"
            >
              {link.name}
            </a>
          ))}
           {onOpenAi && (
            <button
                onClick={() => {
                    setIsOpen(false);
                    onOpenAi();
                }}
                className="text-lg uppercase tracking-widest flex items-center gap-2 text-brand font-medium mt-4"
            >
                <Sparkles size={20} />
                Vision AI Starten
            </button>
           )}
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Portfolio from './components/Portfolio';
import Services from './components/Services';
import Contact from './components/Contact';
import Footer from './components/Footer';
import CustomCursor from './components/CustomCursor';
import Impressum from './components/Impressum';
import Datenschutz from './components/Datenschutz';
import AiModal from './components/AiModal';

const App: React.FC = () => {
  const [route, setRoute] = useState('home');
  const [isAiOpen, setIsAiOpen] = useState(false);

  useEffect(() => {
    const handleNavigation = () => {
      const hash = window.location.hash;
      if (hash === '#impressum') {
        setRoute('impressum');
      } else if (hash === '#datenschutz') {
        setRoute('datenschutz');
      } else {
        setRoute('home');
      }
    };

    const initialHash = window.location.hash;

    if (initialHash === '#impressum' || initialHash === '#datenschutz') {
        try {
            window.history.replaceState(null, '', window.location.pathname);
        } catch (e) {
            console.warn("Could not clean URL history:", e);
        }
        setRoute('home');
        window.scrollTo(0, 0);
    } else {
        handleNavigation();
    }

    window.addEventListener('hashchange', handleNavigation);
    window.addEventListener('popstate', handleNavigation);

    return () => {
        window.removeEventListener('hashchange', handleNavigation);
        window.removeEventListener('popstate', handleNavigation);
    };
  }, []);

  useEffect(() => {
    if (route === 'home') {
      if (window.location.hash && window.location.hash !== '#' && window.location.hash !== '#impressum' && window.location.hash !== '#datenschutz') {
          const id = window.location.hash.replace('#', '');
          setTimeout(() => {
            const element = document.getElementById(id);
            if (element) {
              const elementPosition = element.getBoundingClientRect().top + window.scrollY;
              window.scrollTo({
                  top: elementPosition,
                  behavior: "smooth"
              });
            }
          }, 100);
      } else {
           if (!window.location.hash || window.location.hash === '#') {
               window.scrollTo({ top: 0, behavior: 'smooth' });
           }
      }
    } else {
        window.scrollTo({ top: 0, behavior: 'instant' });
    }
  }, [route]);

  const renderContent = () => {
    switch (route) {
      case 'impressum':
        return <Impressum />;
      case 'datenschutz':
        return <Datenschutz />;
      default:
        return (
          <>
            <Hero />
            <About />
            <Portfolio />
            <Services />
            <Contact />
          </>
        );
    }
  };

  return (
    <div className="bg-[#F9F9F7] min-h-screen text-gray-800 selection:bg-brand selection:text-white overflow-x-hidden">
      <CustomCursor />
      <Navbar onOpenAi={() => setIsAiOpen(true)} />
      <AiModal isOpen={isAiOpen} onClose={() => setIsAiOpen(false)} />
      <main className="min-h-screen">
        {renderContent()}
      </main>
      <Footer />
    </div>
  );
};

export default App;

